#!/usr/bin/env bash
# Retry harness for a PRLM-C run, for a machine where the GPU it needs is busy.
#
#   usage:  RUN=e6 QUERIES=0 bash retry_run.sh
#
# Why this exists: every prlmc_*.yaml sets `device: cuda:0`, which under
# CUDA_VISIBLE_DEVICES refers to the *first visible* GPU, not physical GPU 0.
# On 2026-09-27 E6 died this way twice over: first because GPU 6 was taken
# between the pick and the weight load, then 40 more times because the threshold
# below was lower than the run's actual peak.
#
# Do not edit this file while an instance of it is running. bash reads a script
# incrementally by byte offset, so overwriting it mid-loop makes the next read
# land mid-line; that is how a run of this script once ended in
# "genuine: command not found / syntax error near unexpected token `done'" even
# though every iteration had executed correctly.
# That is fine when the chosen card is free, but this host is shared and a card
# can be taken between the queue decision and the model load, in which case the
# run dies with CUDA OOM at `model.to(device)` and produces an empty output dir.
# So: pick the freest card, wait for a real margin, and retry the whole run.
set -uo pipefail

BENCH=/share/latent/PRLM-C
PY=/share/latent/mllm_env/bin/python
RUN="${RUN:?set RUN, e.g. e6}"
QUERIES="${QUERIES:-0}"
# E6 needs far more than the select_blocks runs. Measured from the OOM:
# 15.10 GiB already allocated plus 3.12 GiB requested is a ~18.2 GB peak, because
# the carrier compactor materialises blocks/carriers/context/delta in fp32 and
# each of those is 1-2 GB at 32 layers x 4096 hidden. A 14 GB threshold let
# 40 consecutive attempts start on a card that could never fit them.
NEED_MB="${NEED_MB:-21000}"
MAX_TRIES="${MAX_TRIES:-40}"
WAIT_S="${WAIT_S:-120}"

cd "$BENCH" || exit 1

pick_gpu() {
  # Highest free memory wins; ties go to the lower index for determinism.
  nvidia-smi --query-gpu=index,memory.used --format=csv,noheader,nounits \
    | awk -F, -v t="$NEED_MB" '
        { gsub(/ /,"",$1); gsub(/ /,"",$2); free = 32768 - $2;
          printf "%s %s\n", free, $1 }
      ' \
    | sort -k1,1nr -k2,2n \
    | awk -v t="$NEED_MB" '$1 >= t { print $2; exit }'
}

for try in $(seq 1 "$MAX_TRIES"); do
  GPU="$(pick_gpu)"
  if [ -z "$GPU" ]; then
    echo "[retry] try $try: no card with ${NEED_MB} MiB free; waiting ${WAIT_S}s"
    nvidia-smi --query-gpu=index,memory.used --format=csv,noheader
    sleep "$WAIT_S"
    continue
  fi

  echo "[retry] try $try: using GPU $GPU ($(date -u))"
  OUT="$BENCH/outputs/prlmc-$RUN"
  rm -rf "$OUT" "$BENCH/methods/prlmc/__pycache__"
  mkdir -p "$OUT" "$BENCH/logs"

  export HF_HUB_OFFLINE=1
  export HF_ENDPOINT=https://hf-mirror.com
  export CUDA_VISIBLE_DEVICES="$GPU"
  export TOKENIZERS_PARALLELISM=false
  export PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True

  "$PY" /share/latent/mllm_patch/batch_run.py \
    configs/data_conf/Conflict_Resolution/Factconsolidation_sh_32k.yaml \
    --agent_config "configs/agent_conf/prlmc_${RUN}.yaml" \
    --chunk 400 \
    --queries "$QUERIES" \
    --bench "$BENCH" > "$BENCH/logs/$RUN.log" 2>&1
  rc=$?

  if [ "$rc" -eq 0 ] && ! grep -q "^FAILED" "$BENCH/logs/$RUN.log"; then
    echo "[retry] $RUN succeeded on GPU $GPU (try $try)"
    exit 0
  fi

  echo "[retry] try $try failed rc=$rc on GPU $GPU; tail:"
  tail -5 "$BENCH/logs/$RUN.log"
  # A genuine code error is not worth 40 retries.
  if ! grep -qiE "out of memory|CUDA error" "$BENCH/logs/$RUN.log"; then
    echo "[retry] failure does not look like contention; stopping"
    exit "$rc"
  fi
  sleep "$WAIT_S"
done

echo "[retry] exhausted $MAX_TRIES tries"
exit 1
